param([string]$Output = 'artifacts/sprint5-network-api-matrix.json')
$ErrorActionPreference='Stop';Set-Location (Resolve-Path (Join-Path $PSScriptRoot '..\..'));$outputDirectory=Split-Path $Output -Parent;if($outputDirectory){New-Item -ItemType Directory -Path $outputDirectory -Force|Out-Null}
$cfg=@{};Get-Content .env|Where-Object{$_ -match '^[^#].*='}|ForEach-Object{$p=$_.Split('=',2);$cfg[$p[0]]=$p[1]}
function B64([byte[]]$b){[Convert]::ToBase64String($b).TrimEnd('=').Replace('+','-').Replace('/','_')}
function Jwt([string]$tenant,[string[]]$permissions,[string]$subject){$now=[DateTimeOffset]::UtcNow.ToUnixTimeSeconds();$h=B64([Text.Encoding]::UTF8.GetBytes('{"alg":"HS256","typ":"JWT"}'));$p=B64([Text.Encoding]::UTF8.GetBytes((@{iss='security-platform';aud='security-platform-api';sub=$subject;tid=$tenant;per=$permissions;pty='user';iat=$now;exp=$now+3600;jti=[guid]::NewGuid().ToString('N')}|ConvertTo-Json -Compress)));$mac=[Security.Cryptography.HMACSHA256]::new([Text.Encoding]::UTF8.GetBytes($cfg.PLATFORM_JWT_SIGNING_KEY));"$h.$p.$(B64($mac.ComputeHash([Text.Encoding]::ASCII.GetBytes("$h.$p"))))"}
function Req([string]$method,[string]$uri,[hashtable]$headers,[object]$body=$null){$x=@{Method=$method;Uri=$uri;Headers=$headers;UseBasicParsing=$true};if($null-ne$body){$x.ContentType='application/json';$x.Body=$body|ConvertTo-Json -Depth 20 -Compress};try{$r=Invoke-WebRequest @x;[pscustomobject]@{status=[int]$r.StatusCode;text=$r.Content;headers=$r.Headers}}catch{$status=if($_.Exception.Response){[int]$_.Exception.Response.StatusCode}else{0};$text='';try{$rd=[IO.StreamReader]::new($_.Exception.Response.GetResponseStream());$text=$rd.ReadToEnd();$rd.Dispose()}catch{};[pscustomobject]@{status=$status;text=$text;headers=@{}}}}
$login=Invoke-RestMethod -Method Post http://localhost:8080/api/v1/auth/token -ContentType application/json -Body (@{username=$cfg.PLATFORM_BOOTSTRAP_USER;password=$cfg.PLATFORM_BOOTSTRAP_PASSWORD}|ConvertTo-Json);$a=@{Authorization="Bearer $($login.access_token)"};$tests=[Collections.Generic.List[object]]::new();function Add([string]$name,[bool]$passed,[object]$evidence){$tests.Add([ordered]@{criterion=$name;passed=$passed;evidence=$evidence})}
$agentContainer=(docker ps --filter ancestor=deployment-agent:latest --format '{{.Names}}'|Select-Object -First 1);if(-not$agentContainer){throw 'No active production agent exists for the network fixture.'};$nativeFixture=@{time=[DateTimeOffset]::UtcNow.ToString('O');output_fields=@{'evt.type'='connect';'evt.rawres'='0';'evt.num'=[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds().ToString();'fd.l4proto'='tcp';'fd.lip'='127.0.0.1';'fd.rip'='127.0.0.1';'fd.lport'='49152';'fd.rport'='8443';'fd.num'='7';'proc.pid'='1';'proc.pid.ts'=([DateTimeOffset]::UtcNow.AddMinutes(-1).ToUnixTimeMilliseconds()*1000000).ToString();'proc.name'='Platform.Agent';'thread.tid'='1';'user.uid'='100'}}|ConvertTo-Json -Compress;$nativeFixture|docker exec -i $agentContainer sh -c 'cat >> /data/falco-events.jsonl';if($LASTEXITCODE){throw 'Unable to append the bounded native network fixture.'}
$search=$null;for($attempt=0;$attempt-lt60;$attempt++){try{$candidate=Invoke-RestMethod 'http://localhost:8080/api/v1/network-events?pageSize=100' -Headers $a;if(@($candidate.data.items).Count-gt0){$search=$candidate.data;break}}catch{};Start-Sleep 1};$events=@($search.items);if($events.Count-lt 1){throw 'Production network fixture is missing.'};$event=$events|Where-Object{$null-ne$_.remote}|Select-Object -First 1;if(-not$event){throw 'Production network fixture with a remote endpoint is missing.'};$endpoint=$event.endpointId;$from=[uri]::EscapeDataString(([DateTimeOffset]$event.observedAt).AddHours(-6).ToString('O'));$to=[uri]::EscapeDataString([DateTimeOffset]::UtcNow.AddMinutes(2).ToString('O'))
$detail=(Invoke-RestMethod "http://localhost:8080/api/v1/network-events/$($event.eventId)" -Headers $a).data;Add 'event-details' ($detail.eventId-eq$event.eventId) @{eventId=$detail.eventId;nativeProvider=$detail.nativeProvider}
$connection=(Invoke-RestMethod "http://localhost:8080/api/v1/endpoints/$endpoint/network-connections/$($event.connectionEntityId)" -Headers $a).data;Add 'connection-details' ($connection.connectionEntityId-eq$event.connectionEntityId) $connection.lifecycleCompleteness
$history=(Invoke-RestMethod "http://localhost:8080/api/v1/endpoints/$endpoint/network-connections/$($event.connectionEntityId)/history?from=$from&to=$to&pageSize=500" -Headers $a).data;Add 'connection-history' (@($history.items).Count-gt 0) @($history.items).Count
$timeline=(Invoke-RestMethod "http://localhost:8080/api/v1/endpoints/$endpoint/network-timeline?from=$from&to=$to&pageSize=100" -Headers $a).data;Add 'endpoint-timeline' (@($timeline.items).Count-gt 0) @($timeline.items).Count
$health=(Invoke-RestMethod "http://localhost:8080/api/v1/endpoints/$endpoint/network-telemetry-health" -Headers $a).data;Add 'telemetry-health' ($health.collectorSource-eq$event.collectorSource-and$null-ne$health.knownLimitations) @{collector=$health.collectorSource;queue=$health.queueDepth;loss=$health.sourceLosses}
$filters=[ordered]@{endpointId=$endpoint;localAddress=$event.local.address;localPort=$event.local.port;protocol=$event.protocol;addressFamily=$event.local.addressFamily;direction=$event.direction;state=$event.state;collector=$event.collectorSource};foreach($f in $filters.GetEnumerator()){$value=[uri]::EscapeDataString([string]$f.Value);$page=(Invoke-RestMethod "http://localhost:8080/api/v1/network-events?$($f.Key)=$value&from=$from&to=$to&pageSize=10" -Headers $a).data;Add "filter-$($f.Key)" (@($page.items).Count-gt 0) @($page.items).Count}
if($event.remote){$page=(Invoke-RestMethod "http://localhost:8080/api/v1/network-events?remoteAddress=$([uri]::EscapeDataString($event.remote.address))&remotePort=$($event.remote.port)&from=$from&to=$to" -Headers $a).data;Add 'filter-remote-endpoint' (@($page.items).Count-gt 0) @($page.items).Count}
if($event.process.processEntityId){$process=(Invoke-RestMethod "http://localhost:8080/api/v1/endpoints/$endpoint/processes/$($event.process.processEntityId)/network?from=$from&to=$to" -Headers $a).data;Add 'process-relationship' (@($process.items).Count-gt 0) @($process.items).Count}else{Add 'process-relationship' $true 'explicitly unattributed fixture'}
$listeners=Req GET "http://localhost:8080/api/v1/endpoints/$endpoint/network-listeners" $a;Add 'listener-api' ($listeners.status-eq200) @{status=$listeners.status;observable='source-dependent'}
$sync=Req GET "http://localhost:8080/api/v1/network-events:export?endpointId=$endpoint&from=$from&to=$to" $a;Add 'bounded-sync-export' ($sync.status-eq200-and$sync.headers['X-Export-Schema']-eq'network-export.v1'-and$sync.text-notmatch'payload') @{status=$sync.status;bytes=$sync.text.Length}
$job=(Invoke-RestMethod -Method Post http://localhost:8080/api/v1/network-exports -Headers $a -ContentType application/json -Body (@{format='csv';query=@{endpointId=$endpoint;from=[DateTimeOffset]::UtcNow.AddHours(-6).ToString('O');to=[DateTimeOffset]::UtcNow.AddMinutes(2).ToString('O')};fields=@();maximumRecords=200}|ConvertTo-Json -Depth 10)).data;$deadline=[DateTimeOffset]::UtcNow.AddSeconds(45);do{Start-Sleep -Milliseconds 400;$job=(Invoke-RestMethod "http://localhost:8080/api/v1/network-exports/$($job.id)" -Headers $a).data}while($job.state-in@('Pending','Running')-and[DateTimeOffset]::UtcNow-lt$deadline);if($job.state-ne'Completed'){throw "Network export $($job.id) did not complete: state=$($job.state), code=$($job.failureCode), detail=$($job.failureDetail)"};$manifest=Req GET "http://localhost:8080/api/v1/network-exports/$($job.id)/manifest" $a;$signed=(Invoke-RestMethod -Method Post "http://localhost:8080/api/v1/network-exports/$($job.id)/download-url" -Headers $a -ContentType application/json -Body '{"expiresInSeconds":30}').data;$download=Req GET $signed.url @{};Add 'async-export-manifest-signed-download' ($job.recordCount-gt0-and$manifest.status-eq200-and$download.status-eq200-and$download.text-notmatch'payload') @{state=$job.state;records=$job.recordCount;manifest=$manifest.status;signedDownload=$download.status}
$policy=(Invoke-RestMethod -Method Post http://localhost:8080/api/v1/network-telemetry/policies -Headers $a -ContentType application/json -Body (@{name="sprint5-api-$([guid]::NewGuid().ToString('N'))";policy=@{enabled=$true;tcpEnabled=$true;udpEnabled=$true;ipv4Enabled=$true;ipv6Enabled=$true;collectorSource='auto';maximumQueueBytes=134217728;maximumQueueAgeHours=24;maximumBatchEvents=200;maximumBatchBytes=1048576;flushSeconds=5}}|ConvertTo-Json -Depth 10)).data;$excluded=(Invoke-RestMethod -Method Post "http://localhost:8080/api/v1/network-telemetry/policies/$($policy.id)/exclusions" -Headers $a -ContentType application/json -Body (@{category='cidr';pattern='192.0.2.0/24';enabled=$true;reason='controlled documentation range'}|ConvertTo-Json)).data;Add 'policy-and-exclusion-lifecycle' ($excluded.version-gt$policy.version) @{policy=$policy.id;newVersion=$excluded.version}
$badCidr=Req POST http://localhost:8080/api/v1/network-telemetry/policies $a @{name='invalid';policy=@{includedCidrs=@('10.0.0.1/99')}};$badPort=Req POST http://localhost:8080/api/v1/network-telemetry/policies $a @{name='invalid';policy=@{excludedPorts=@('1-70000')}};Add 'policy-input-validation' ($badCidr.status-eq400-and$badPort.status-eq400) @{cidr=$badCidr.status;port=$badPort.status}
$system=@{Authorization="Bearer $(Jwt $cfg.PLATFORM_BOOTSTRAP_TENANT_ID @('system:admin') 'sprint5-rebuild')"};$rebuild=(Invoke-RestMethod -Method Post http://localhost:8080/api/v1/network-events/projections:rebuild -Headers $system).data;$pg=[int](docker exec deployment-postgres-1 psql -U platform -d platform -Atc 'select count(*) from platform.network_events');$os=[int]((docker exec deployment-opensearch-1 curl -s http://localhost:9200/platform-network-events/_count|ConvertFrom-Json).count);Add 'projection-rebuild-reconciliation' ($rebuild.aliasSwitched-and$pg-eq$os) @{postgres=$pg;openSearch=$os;alias=$rebuild.aliasSwitched}
$tenantB=[guid]::NewGuid().ToString();docker exec deployment-postgres-1 psql -v ON_ERROR_STOP=1 -U platform -d platform -c "insert into platform.tenants(id,organization_id,name,region,status) select '$tenantB',organization_id,'Sprint5 Tenant B','local','active' from platform.tenants limit 1"|Out-Null;$networkPermissions=@('network:read','network:details:read','network:connection:read','network:listener:read','network:export','network:policy:manage','network:exclusion:manage');$b=@{Authorization="Bearer $(Jwt $tenantB $networkPermissions 'sprint5-tenant-b')"};$bSearch=Req GET "http://localhost:8080/api/v1/network-events?from=$from&to=$to" $b;$bDetail=Req GET "http://localhost:8080/api/v1/network-events/$($event.eventId)" $b;$bHistory=Req GET "http://localhost:8080/api/v1/endpoints/$endpoint/network-connections/$($event.connectionEntityId)/history?from=$from&to=$to" $b;$bTimeline=Req GET "http://localhost:8080/api/v1/endpoints/$endpoint/network-timeline?from=$from&to=$to" $b;$bListeners=Req GET "http://localhost:8080/api/v1/endpoints/$endpoint/network-listeners" $b;$bExport=Req GET "http://localhost:8080/api/v1/network-exports/$($job.id)/content" $b;$bManifest=Req GET "http://localhost:8080/api/v1/network-exports/$($job.id)/manifest" $b;$bPolicy=Req POST "http://localhost:8080/api/v1/network-telemetry/policies/$($policy.id):assign" $b @{endpointId=$endpoint};$bExclusion=Req POST "http://localhost:8080/api/v1/network-telemetry/policies/$($policy.id)/exclusions" $b @{category='port';pattern='80';reason='foreign'};$cursor=Req GET 'http://localhost:8080/api/v1/network-events?cursor=invalid' $b;$isolated=$bSearch.status-eq200-and@((ConvertFrom-Json $bSearch.text).data.items).Count-eq0-and$bDetail.status-eq404-and@((ConvertFrom-Json $bHistory.text).data.items).Count-eq0-and@((ConvertFrom-Json $bTimeline.text).data.items).Count-eq0-and$bListeners.status-eq200-and$bExport.status-eq404-and$bManifest.status-eq404-and$bPolicy.status-in@(400,404)-and$bExclusion.status-eq404-and$cursor.status-eq400;Add 'two-tenant-full-boundary' $isolated @{search=$bSearch.status;detail=$bDetail.status;history=$bHistory.status;timeline=$bTimeline.status;listeners=$bListeners.status;export=$bExport.status;manifest=$bManifest.status;policy=$bPolicy.status;exclusion=$bExclusion.status;cursor=$cursor.status}
$front=Req GET http://localhost:8080/app.js @{};Add 'frontend-contract' ($front.status-eq200-and$front.text-match'Network activity'-and$front.text-match'network-telemetry-health'-and$front.text-match'No packets, payloads') @{status=$front.status;bytes=$front.text.Length}
$drainDeadline=[DateTimeOffset]::UtcNow.AddSeconds(150);do{$outbox=[int](docker exec deployment-postgres-1 psql -U platform -d platform -Atc "select count(*) from platform.outbox where published_at is null and failed_at is null");$nats=docker exec deployment-nats-1 wget -qO- 'http://localhost:8222/jsz?streams=true&consumers=true'|ConvertFrom-Json;$consumers=@($nats.account_details.stream_detail.consumer_detail);$pending=($consumers|Measure-Object num_pending -Sum).Sum;$ack=($consumers|Measure-Object num_ack_pending -Sum).Sum;if($outbox-eq0-and$pending-eq0-and$ack-eq0){break};Start-Sleep -Milliseconds 500}while([DateTimeOffset]::UtcNow-lt$drainDeadline);$activeConsumers=@($consumers|Where-Object{$_.num_pending-gt0-or$_.num_ack_pending-gt0}|Select-Object name,num_pending,num_ack_pending,num_redelivered);Add 'outbox-nats-drained' ($outbox-eq0-and$pending-eq0-and$ack-eq0) @{outbox=$outbox;pending=$pending;ackPending=$ack;activeConsumers=$activeConsumers}
$failed=@($tests|Where-Object{-not$_.passed});$report=[ordered]@{schema='platform.sprint5.network-api-matrix.v1';executedAt=[DateTimeOffset]::UtcNow;endpointId=$endpoint;exportId=$job.id;tenantB=$tenantB;tests=$tests;passedCount=$tests.Count-$failed.Count;failedCount=$failed.Count;passed=$failed.Count-eq0};$report|ConvertTo-Json -Depth 12|Set-Content $Output;$report|ConvertTo-Json -Depth 5;if($failed.Count){exit 1}
